-- Vistto · migração 28: atualiza as máquinas com a leitura do ObraSoft de 25/11/2026 (só leitura no ObraSoft)
-- 1) inclui as máquinas novas  2) corrige a descrição das que mudaram no ObraSoft (mesma placa)
-- 3) DESATIVA (não apaga) as que saíram do ObraSoft: continuam no histórico das inspeções, só somem da escolha.
begin;
create temp table _os(tipo text, id text, prefixo text, modelo text, serie text, descricao text, origem text) on commit drop;
create temp table _n on commit drop as select o.*, upper(regexp_replace(o.descricao,'\s+',' ','g')) k from _os o;
create temp table _e on commit drop as select e.id, e.tipo, e.ativo, upper(regexp_replace(e.descricao,'\s+',' ','g')) k from public.equipamentos e;
create temp table _casou on commit drop as select n.*, e.id eid from _n n join _e e on e.tipo = n.tipo and e.k = n.k;
create temp table _renom on commit drop as select n.*, e.id eid from _n n join _e e on e.id = n.id and e.tipo = n.tipo
  where not exists (select 1 from _casou c where c.tipo = n.tipo and c.k = n.k) and not exists (select 1 from _n n2 where n2.tipo = e.tipo and n2.k = e.k);
create temp table _novos on commit drop as select n.* from _n n where not exists (select 1 from _casou c where c.tipo = n.tipo and c.k = n.k) and not exists (select 1 from _renom r where r.id = n.id);
create temp table _sai on commit drop as select e.id from _e e where e.ativo and not exists (select 1 from _n n where n.tipo = e.tipo and n.k = e.k) and not exists (select 1 from _renom r where r.eid = e.id);
do $$ begin
  if (select count(*) from _novos) > 60 or (select count(*) from _sai) > 40 then raise exception 'Diferença maior que a prevista (novos %, saem %) — parei sem mudar nada', (select count(*) from _novos), (select count(*) from _sai); end if;
end $$;
update public.equipamentos e set descricao = r.descricao, modelo = r.modelo, prefixo = r.prefixo, serie = r.serie, ativo = true, origem = r.origem from _renom r where e.id = r.eid;
update public.equipamentos e set ativo = true from _casou c where e.id = c.eid and not e.ativo;
  select case when exists (select 1 from public.equipamentos x where x.id = n.id) then n.id || '-' || substr(md5(n.descricao), 1, 5) else n.id end,
         n.tipo, n.prefixo, n.modelo, n.serie, n.descricao, true, n.origem from _novos n;
update public.equipamentos e set ativo = false from _sai s where e.id = s.id;
select (select count(*) from _novos) as incluidas, (select count(*) from _renom) as corrigidas, (select count(*) from _sai) as desativadas,
       (select count(*) from public.equipamentos where ativo) as ativas_agora, (select count(*) from public.equipamentos) as total;
commit;
